--
-- Table structure for table `reservations`
--

DROP TABLE IF EXISTS `reservations`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `reservations` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `cabin_id` bigint NOT NULL,
  `tourist_id` bigint NOT NULL,
  `start_date` date NOT NULL,
  `end_date` date NOT NULL,
  `adults` int NOT NULL,
  `children` int NOT NULL DEFAULT '0',
  `status` enum('PENDING','ACCEPTED','REJECTED','CANCELLED') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'PENDING',
  `owner_comment` varchar(400) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `tourist_note` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `total_price_rsd` int NOT NULL,
