INSERT INTO `reviews` VALUES (1,1,4.5,'Odlicna vikendica sa prelepim pogledom! Sve je bilo savrseno organizovano.','2024-12-24 11:00:00'),(2,2,5.0,'Neverovatno iskustvo! Spa centar je bio fantastican, preporucujem svima.','2024-11-19 14:30:00'),(3,3,4.0,'Dobra lokacija za avanturiste. Rafting je bio uzbudljiv, ali vikendica je mogla biti cisca.','2024-10-14 08:45:00'),(4,4,4.8,'Sjajno mesto za ljubitelje vina! Terasa sa pogledom na vinograd je bila savrsena.','2024-09-09 12:20:00'),(5,5,3.5,'Dobro za ekoloski turizam, ali udaljeno od gradskih sadrzaja.','2024-08-24 14:10:00'),(6,8,4.2,'Prelepa vikendica na Zlatiboru. Kamin je bio posebno prijatan.','2025-04-19 09:30:00'),(7,9,4.7,'Izvanredna sauna i jacuzzi! Savrseno za zimski odmor.','2025-05-24 11:45:00'),(8,10,3.8,'Dobra lokacija za ribolov, ali internet je bio slab.','2025-06-13 07:15:00'),(9,25,4.5,'Odlicna vikendica za porodicu, deca su uzivala u igraonici!','2024-05-14 08:00:00'),(10,26,4.0,'Dobro mesto, ali malo skupo za ono sto nude.','2024-06-19 09:00:00'),(11,27,1.5,'Razocaran sam. Vikendica nije bila cista, wifi nije radio.','2024-07-24 10:00:00'),(12,28,1.0,'Uzasno iskustvo! Klima nije radila, niko se nije javljao na telefon.','2024-08-29 11:00:00'),(13,29,1.2,'Ne preporucujem. Oprema je stara i dotrajala, los odnos cene i kvaliteta.','2024-10-04 12:00:00'),(14,30,4.8,'Spa centar je bio fantastican! Pravo mesto za opustanje.','2024-05-16 08:00:00'),(15,31,4.2,'Dobra lokacija i udoban krevet. Preporucujem.','2024-06-21 09:00:00'),(16,32,1.8,'Wellness centar je bio zatvoren tokom naseg boravka. Osecam se prevareno.','2024-07-26 10:00:00'),(17,33,1.3,'Lose odrzavanje. Sauna nije radila, bazen je bio prljav.','2024-08-31 11:00:00'),(18,34,1.1,'Najgore iskustvo ikada. Osoblje neprijatno, uslovi neprihvatljivi.','2024-10-06 12:00:00'),(19,35,4.3,'Odlican pogled na manastire! Idealno za kulturni turizam.','2024-04-14 08:00:00'),(20,36,3.9,'Dobro, ali malo daleko od centra Fruske Gore.','2024-05-19 09:00:00'),(21,37,1.6,'Razocaravajuce. Parking je bio nemoguc, a vikendica prljava.','2024-06-24 10:00:00'),(22,38,1.4,'Lose iskustvo. Klima nije radila usred leta, zahtevali smo refundaciju.','2024-07-29 11:00:00'),(23,39,1.9,'Ne preporucujem. Internet spor, topla voda nije radila.','2024-09-03 12:00:00'),(24,6,4.6,'Fantasticna vikendica! Sauna je bila odlicna, pogled predivan.','2025-02-14 09:00:00'),(25,7,4.3,'Lepa lokacija pored jezera, camac je bilo zgodan za koriscenje.','2025-03-10 10:00:00'),(26,73,4.0,'Lepo','2025-11-03 09:38:00');
